def check_exists_bibd_avoiding(n, k, avoided_triangles):
    all_triangles = [t for t in itertools.combinations(range(n), 3) if t not in avoided_triangles]
    edges = list(itertools.combinations(range(n), 2))

    # We need to pick k*n*(n-1)//6 triangles.
    num_needed = n * k * (n - 1) // 6

    # Use backtracking to find if such a set exists.
    def backtrack(idx, current_set, edge_counts):
        if len(current_set) == num_needed:
            if all(count == k for count in edge_counts.values()):
                return True
            return False

        if idx == len(all_triangles):
            return False

        # Optimization: if we can't reach the needed number of triangles, stop.
        if len(current_set) + (len(all_triangles) - idx) < num_needed:
            return False

        # Try including all_triangles[idx]
        t = all_triangles[idx]
        possible = True
        for e in itertools.combinations(t, 2):
            if edge_counts[e] + 1 > k:
                possible = False
                break

        if possible:
            for e in itertools.combinations(t, 2):
                edge_counts[e] += 1
            if backtrack(idx + 1, current_set + [t], edge_counts):
                return True
            for e in itertools.combinations(t, 2):
                edge_counts[e] -= 1

        # Try excluding all_triangles[idx]
        if backtrack(idx + 1, current_set, edge_counts):
            return True

        return False

    edge_counts = {e: 0 for e in edges}
    return backtrack(0, [], edge_counts)

