import itertools

def min_mono_lp(n, k, coloring):
    triangles = list(itertools.combinations(range(n), 3))
    edges = list(itertools.combinations(range(n), 2))

    c = []
    for t in triangles:
        if coloring[t[0]] == coloring[t[1]] == coloring[t[2]]:
            c.append(1)
        else:
            c.append(0)

    A = []
    for e in edges:
        row = []
        for t in triangles:
            if e[0] in t and e[1] in t:
                row.append(1)
            else:
                row.append(0)
        A.append(row)

    b = [k] * len(edges)

    res = linprog(c, A_eq=A, b_eq=b, bounds=(0, None), method='highs')
    return res.fun

